#include <iostream>
#include <iomanip>

bool isLeapYear(int year) {
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

int getNumberOfDaysInMonth(int year, int month) {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return isLeapYear(year) ? 29 : 28;
        default:
            return 0;
    }
}

int getTotalNumberOfDays(int year, int month) {
    int total = 0;
    for (int y = 1800; y < year; ++y) {
        total += isLeapYear(y) ? 366 : 365;
    }
    for (int m = 1; m < month; ++m) {
        total += getNumberOfDaysInMonth(year, m);
    }
    return total;
}

int getStartDay(int year, int month) {
    constexpr int startDay1800 = 3; // Jan 1, 1800 was Wednesday
    return (getTotalNumberOfDays(year, month) + startDay1800) % 7;
}

int main() {
    int year = 2012;
    int month = 3;

    std::cout << "            March " << year << "\n";
    std::cout << "-----------------------------\n";
    std::cout << " Sun Mon Tue Wed Thu Fri Sat\n";

    int startDay = getStartDay(year, month);
    int numberOfDaysInMonth = getNumberOfDaysInMonth(year, month);

    for (int i = 0; i < startDay; ++i) {
        std::cout << "    ";
    }

    for (int i = 1; i <= numberOfDaysInMonth; ++i) {
        std::cout << std::setw(4) << i;
        if ((i + startDay) % 7 == 0) {
            std::cout << "\n";
        }
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>

bool isEven(int n) {
    return n % 2 == 0;
}

[[nodiscard]] int calculateSum(int a, int b) {
    return a + b;
}

void reportParity(int number) {
    std::cout << number << " is " << (isEven(number) ? "even" : "odd") << ".\n";
}

int main() {
    reportParity(42);
    reportParity(17);

    int result = calculateSum(10, 25);
    std::cout << "Sum: " << result << "\n";

    return 0;
}
